import { element } from 'tsx-vanilla';

import { SpellSchool } from '../../proto/common.js';
import { formatToCompactNumber, formatToPercent } from '../../utils.js';

// Maps the proto SpellSchool enum to the CSS class suffix used for bar coloring
// (see the $spell-school-colors map in _detailed_results.scss).
const spellSchoolCssNames: Record<number, string> = {
	[SpellSchool.SpellSchoolPhysical]: 'physical',
	[SpellSchool.SpellSchoolArcane]: 'arcane',
	[SpellSchool.SpellSchoolFire]: 'fire',
	[SpellSchool.SpellSchoolFrost]: 'frost',
	[SpellSchool.SpellSchoolHoly]: 'holy',
	[SpellSchool.SpellSchoolNature]: 'nature',
	[SpellSchool.SpellSchoolShadow]: 'shadow',
};

export interface MetricsTotalBarProps {
	// Percentage shown on the left (this action's share of the total).
	percentage: number | undefined | null;
	// Largest value across all rows, used to scale the bar fill width.
	max: number | null;
	// Value shown on the right (compact formatted).
	total: number;
	// Value used to scale the bar fill width relative to max.
	value: number;
	// When set, colors the bar by spell school. Falls back to classColor, then currentColor.
	spellSchool?: SpellSchool | undefined | null;
	classColor?: string | undefined | null;
}

// Renders a "percentage | colored bar | compact total" cell, matching the
// Cataclysm detailed-results bar UI.
export function MetricsTotalBar({ percentage, max, total, value, spellSchool, classColor }: MetricsTotalBarProps): HTMLElement {
	const schoolName = typeof spellSchool === 'number' ? spellSchoolCssNames[spellSchool] : undefined;
	const fillWidth = formatToPercent((value / (max || 1)) * 100);

	const container = (
		<div className="metrics-total">
			<div className="metrics-total-percentage">{formatToPercent(percentage || 0)}</div>
			<div className="metrics-total-bar">
				<div className="metrics-total-bar-fill"></div>
			</div>
			<div className="metrics-total-amount">{formatToCompactNumber(total)}</div>
		</div>
	) as HTMLElement;

	const fill = container.querySelector('.metrics-total-bar-fill') as HTMLElement;
	if (schoolName) {
		fill.classList.add(`bg-spell-school-${schoolName}`);
	} else if (classColor) {
		fill.classList.add(`bg-${classColor.toLowerCase()}`);
	}
	fill.style.setProperty('--percentage', fillWidth);

	return container;
}
